export async function signIn(page: Page, username: string, password: string) {
    await page.getByTestId("username-input").fill(username);
    await page.getByTestId("password-input").fill(password);
    await page.getByTestId("submit-login-button").click();
    await page.waitForURL((u) => !u.pathname.startsWith('/login'));
}

export async function openHighlightsLibrary(page: Page) {
    await page.getByRole("link", { name: " Highlights" }).click();
    await page.getByTestId("highlights-empty").waitFor({ state: "visible", timeout: 10000 });
}

export async function applyColorFilter(page: Page, testId: string) {
    await page.getByTestId(testId).click();
    await page.getByTestId("highlights-empty").waitFor({ state: "visible", timeout: 10000 });
}
